"\nfrom PIL import Image, ImageDraw\nimport math, random\n\n# ---------- constants ----------\nWIDTH, HEIGHT = 1920, 1080\nFPS = 30\nSHOT_FRAMES = int(3.3 * FPS)          # \u224899, use 100 for convenience\nTOTAL_FRAMES = SHOT_FRAMES\n\nPARCHMENT  = (245, 235, 210, 255)\nINK        = ( 30,  25,  20, 255)     # dark ink\nINK_LIGHT  = ( 80,  70,  60, 255)\nGOLD       = (255, 215,   0, 255)\nGOLD_LIGHT = (255, 235, 100, 255)\nGOLD_DARK  = (200, 170,   0, 255)\n\n# ---------- helper drawing functions ----------\ndef _progress(t, start=0, end=1):\n    \"\"\"Clamp t between 0 and 1 and return interpolated value.\"\"\"\n    return start + (end - start) * max(0, min(t, 1))\n\ndef _line(draw, pt1, pt2, t, color, width=2):\n    \"\"\"Draw a line from pt1 to pt2 only the first fraction t.\"\"\"\n    if t <= 0 or not (pt1 and pt2):\n        return\n    x1, y1 = pt1\n    x2, y2 = pt2\n    if t < 1:\n        x2 = x1 + (x2 - x1) * t\n        y2 = y1 + (y2 - y1) * t\n    draw.line([x1, y1, x2, y2], fill=color, width=width)\n\ndef _circle(draw, center, radius, t, fill=None, outline=None, width=2):\n    \"\"\"Draw a circle (full or swept as an arc) up to fraction t.\"\"\"\n    if t <= 0:\n        return\n    cx, cy = center\n    bbox = [cx - radius, cy - radius, cx + radius, cy + radius]\n    if fill and t >= 1:\n        draw.ellipse(bbox, fill=fill)\n    if outline:\n        if t < 1:\n            draw.arc(bbox, 0, 360 * t, fill=outline, width=width)\n        else:\n            draw.ellipse(bbox, outline=outline, width=width)\n\ndef _gold_shimmer(draw, x, y, t, size=6):\n    \"\"\"Draw a small gold dot with brightness that flickers with t.\"\"\"\n    brightness = 0.7 + 0.3 * math.sin(t * 4 * math.pi)\n    r = int(GOLD[0] * brightness)\n    g = int(GOLD[1] * brightness)\n    b = int(GOLD[2] * brightness)\n    color = (r, g, b, 255)\n    draw.ellipse([x - size, y - size, x + size, y + size], fill=color)\n\n# ---------- scene definitions ----------\nSCENE_FUNCTIONS = []\n\n# --- s001 : ink spiral with gold dots ---\ndef scene_s001(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    cx, cy = WIDTH // 2, HEIGHT // 2\n    max_r = 400\n    turns = 3\n    steps = 300\n\n    # generate spiral points\n    spiral = []\n    for i in range(steps + 1):\n        frac = i / steps\n        r = frac * max_r\n        a = turns * 2 * math.pi * frac\n        x = cx + r * math.cos(a)\n        y = cy + r * math.sin(a)\n        spiral.append((x, y))\n\n    # draw ink spiral progressively\n    n_seg = int(t * steps)\n    for i in range(n_seg):\n        draw.line([spiral[i], spiral[i + 1]], fill=INK, width=3)\n\n    # gold dots appear gradually, with some extra sparkle\n    n_dots = int(t * 25)\n    for i in range(n_dots):\n        idx = int((i / 25) * steps)\n        x, y = spiral[idx]\n        _gold_shimmer(draw, x, y, t + i * 0.1, size=5 + 2 * t)\n\n    # central gold ornament\n    _circle(draw, (cx, cy), 12, t, fill=GOLD_DARK, outline=GOLD, width=2)\n    return img\nSCENE_FUNCTIONS.append(scene_s001)\n\n# --- s002 : ink tree with gold leaves ---\ndef scene_s002(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    def branch(x, y, length, angle, depth, max_depth=6):\n        if depth > max_depth or length < 4:\n            return\n        end_x = x + length * math.cos(angle)\n        end_y = y + length * math.sin(angle)\n        frac = (max_depth - depth) / max_depth   # 0 at trunk, 1 at tip\n\n        # draw branch gradually\n        branch_t = min(1, max(0, (t - frac * 0.3) / 0.7))\n        _line(draw, (x, y), (end_x, end_y), branch_t, INK, width=int(6 * frac + 2))\n\n        # gold leaf at tip if branch fully drawn and depth > 3\n        if branch_t >= 1 and depth > 3:\n            leaf_size = 0.03 * length\n            _circle(draw, (end_x, end_y), leaf_size, t, fill=GOLD, outline=GOLD_DARK)\n\n        # recurse \u2013 sub\u2011branches only if current branch is fully drawn\n        if branch_t < 1:\n            return\n        sub_t = (t - 0.6) / 0.4   # sub\u2011branches start after 60%\n        if sub_t <= 0:\n            return\n        branch(end_x, end_y, length * 0.65, angle + 0.4, depth + 1, max_depth)\n        branch(end_x, end_y, length * 0.65, angle - 0.4, depth + 1, max_depth)\n\n    # start trunk\n    trunk_base = (WIDTH // 2, HEIGHT - 50)\n    branch(*trunk_base, 400, -math.pi / 2, 1, max_depth=7)\n    return img\nSCENE_FUNCTIONS.append(scene_s002)\n\n# --- s003 : illuminated script ---\ndef scene_s003(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    # decorative gold initial box\n    box_x, box_y = 200, 300\n    box_size = 160\n    if t >= 0.1:\n        dt = (t - 0.1) / 0.3\n        draw.rectangle([box_x, box_y, box_x + box_size, box_y + box_size],\n                       outline=GOLD, width=4)\n        # gold fill sweeping in\n        if dt > 0:\n            fill_w = box_size * min(1, dt)\n            draw.rectangle([box_x + 4, box_y + 4,\n                            box_x + 4 + fill_w, box_y + box_size - 4],\n                           fill=GOLD_LIGHT)\n    # ink letter 'A' inside box (appears after box fill)\n    if t > 0.4:\n        letter_t = (t - 0.4) / 0.3\n        # simple 'A' shape\n        mid = box_x + box_size // 2\n        top = box_y + 30\n        left = box_x + 30\n        right = box_x + box_size - 30\n        bottom = box_y + box_size - 30\n        _line(draw, (left, bottom), (mid, top), letter_t, INK, width=6)\n        _line(draw, (mid, top), (right, bottom), letter_t, INK, width=6)\n        _line(draw, (left + 30, (top + bottom)//2),\n              (right - 30, (top + bottom)//2), letter_t, INK, width=4)\n\n    # ink script lines that gradually appear\n    lines = [\n        (350, 500, 1600, 500),\n        (350, 600, 1700, 600),\n        (350, 700, 1500, 700),\n        (350, 800, 1650, 800),\n    ]\n    line_t = (t - 0.5) / 0.5\n    if line_t > 0:\n        for i, (x1, y1, x2, y2) in enumerate(lines):\n            delay = i * 0.12\n            lt = max(0, min(1, (line_t - delay) / (1 - delay)))\n            if lt > 0:\n                # draw as a wavy line (several small segments)\n                segs = 40\n                for s in range(int(lt * segs)):\n                    f1 = s / segs\n                    f2 = (s + 1) / segs\n                    px1 = x1 + (x2 - x1) * f1\n                    py1 = y1 + 10 * math.sin(f1 * 12 + i)\n                    px2 = x1 + (x2 - x1) * f2\n                    py2 = y1 + 10 * math.sin(f2 * 12 + i)\n                    draw.line([px1, py1, px2, py2], fill=INK, width=2)\n    # gold ornaments at paragraph start\n    for i, (x1, y1, _, _) in enumerate(lines):\n        if t > 0.6 + i * 0.08:\n            _gold_shimmer(draw, x1 - 20, y1, t, size=4)\n    return img\nSCENE_FUNCTIONS.append(scene_s003)\n\n# --- s004 : mandala (ink + gold) ---\ndef scene_s004(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    cx, cy = WIDTH // 2, HEIGHT // 2\n    max_r = 400\n    petals = 12\n\n    # outer ring of arcs (ink)\n    n_arc = int(t * 40)\n    for i in range(n_arc):\n        angle = (i / 40) * 2 * math.pi\n        r = max_r\n        x1 = cx + r * math.cos(angle) - 5\n        y1 = cy + r * math.sin(angle) - 5\n        x2 = cx + r * math.cos(angle) + 5\n        y2 = cy + r * math.sin(angle) + 5\n        draw.arc([x1 - r, y1 - r, x2 + r, y2 + r], angle, angle + 0.3,\n                 fill=INK, width=2)\n\n    # gold petals\n    petal_t = (t - 0.3) / 0.7\n    if petal_t > 0:\n        for i in range(petals):\n            theta = i / petals * 2 * math.pi\n            start_r = 100\n            end_r = max_r - 30\n            # radius increases with progress\n            r_now = start_r + (end_r - start_r) * min(1, petal_t * 3 - i * 0.2)\n            if r_now > start_r:\n                # petal shape as ellipse\n                ex = cx + (start_r + r_now) / 2 * math.cos(theta)\n                ey = cy + (start_r + r_now) / 2 * math.sin(theta)\n                width_p = 40 + 20 * math.sin(i * 2.5)\n                height_p = (r_now - start_r)\n                # rotate ellipse (approximation by scaled circle)\n                draw.ellipse([ex - width_p/2, ey - height_p/2,\n                              ex + width_p/2, ey + height_p/2],\n                             fill=GOLD if i % 2 == 0 else GOLD_DARK)\n\n    # center gold circle\n    _circle(draw, (cx, cy), 50, t, fill=GOLD, outline=INK, width=3)\n    return img\nSCENE_FUNCTIONS.append(scene_s004)\n\n# --- s005 : ink mountains with gold sun ---\ndef scene_s005(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    # mountains \u2013 triangular peaks (ink)\n    peaks = [\n        (200, 800, 500, 300, 800, 800),\n        (600, 850, 900, 200, 1300, 850),\n        (1100, 800, 1500, 400, 1900, 800),\n    ]\n    for x1, y1, x2, y2, x3, y3 in peaks:\n        # draw line by line (fill with horizontal lines for texture)\n        n_line = int(t * 120)\n        for i in range(n_line):\n            frac = i / 100\n            y = y2 + (y1 - y2) * frac\n            left_x = x1 + (x2 - x1) * frac\n            right_x = x3 + (x2 - x3) * frac\n            draw.line([left_x, y, right_x, y], fill=INK, width=1)\n        # outline\n        if t > 0.8:\n            draw.polygon([x1, y1, x2, y2, x3, y3], outline=INK, width=2)\n\n    # gold sun rises behind mountains\n    sun_t = (t - 0.2) / 0.6\n    if sun_t > 0:\n        sun_cx, sun_cy = 1400, 900 - 300 * sun_t\n        sun_r = 80\n        _circle(draw, (sun_cx, sun_cy), sun_r, t, fill=GOLD, outline=GOLD_DARK)\n        # rays\n        for angle in range(0, 360, 30):\n            rad = math.radians(angle)\n            x_end = sun_cx + (sun_r + 20) * math.cos(rad)\n            y_end = sun_cy + (sun_r + 20) * math.sin(rad)\n            _line(draw, (sun_cx, sun_cy), (x_end, y_end),\n                  t, GOLD_LIGHT, width=2)\n    return img\nSCENE_FUNCTIONS.append(scene_s005)\n\n# --- s006 : intersecting arcs with gold intersections ---\ndef scene_s006(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    cx, cy = WIDTH // 2, HEIGHT // 2\n    rad = 300\n    # arcs of two circles placed offset\n    centers = [(cx - 150, cy), (cx + 150, cy), (cx, cy - 150), (cx, cy + 150)]\n    for index, (ox, oy) in enumerate(centers):\n        delay = index * 0.2\n        local_t = max(0, min(1, (t - delay) / (1 - delay)))\n        if local_t > 0:\n            # draw arcs from 0 to 180 deg\n            draw.arc([ox - rad, oy - rad, ox + rad, oy + rad],\n                     0, 180 * local_t, fill=INK, width=3)\n    # gold circles at intersections\n    inters = [(cx, cy), (cx - 150, cy - 150), (cx + 150, cy - 150),\n              (cx - 150, cy + 150), (cx + 150, cy + 150)]\n    for i, (x, y) in enumerate(inters):\n        if t > 0.5 + i * 0.08:\n            _circle(draw, (x, y), 20, t, fill=GOLD, outline=GOLD_DARK, width=2)\n    return img\nSCENE_FUNCTIONS.append(scene_s006)\n\n# --- s007 : ink waves with gold highlights ---\ndef scene_s007(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    # several sine waves with different amplitudes and phases\n    for wave in range(5):\n        phase = wave * 0.8\n        amp = 30 + wave * 15\n        y_base = 200 + wave * 180\n        n_pts = int(t * 50)\n        pts = []\n        for i in range(n_pts):\n            x = i * 40\n            y = y_base + amp * math.sin(x / 80 + phase + t * 2)\n            pts.append((x, y))\n        if pts:\n            draw.line(pts, fill=INK if wave % 2 == 0 else INK_LIGHT, width=3 + wave)\n\n        # gold highlights at crests\n        if t > 0.3:\n            crest_t = (t - 0.3) / 0.7\n            for i in range(10):\n                x_crest = (i / 10) * WIDTH\n                y_crest = y_base + amp * math.sin(x_crest / 80 + phase + t * 2)\n                if abs(y_crest - (y_base - amp)) < 2:  # near crest\n                    _gold_shimmer(draw, x_crest, y_crest, t + i, size=4)\n    return img\nSCENE_FUNCTIONS.append(scene_s007)\n\n# --- s008 : shield with gold inlay ---\ndef scene_s008(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    # shield shape made of two overlapping polygons\n    cx, cy = WIDTH // 2, HEIGHT // 2\n    shield = []\n    # approximate shield shape: semi\u2011circle on top, inverted triangle on bottom\n    for angle in range(0, 181, 10):\n        r = 300\n        x = cx + r * math.cos(math.radians(angle))\n        y = cy - 100 + r * math.sin(math.radians(angle))\n        shield.append((x, y))\n    # bottom triangle\n    shield.append((cx - 200, cy + 200))\n    shield.append((cx, cy + 300))\n    shield.append((cx + 200, cy + 200))\n    # close\n    shield.append(shield[0])\n\n    # draw outline gradually\n    n_outline = int(t * len(shield))\n    for i in range(n_outline - 1):\n        draw.line([shield[i], shield[i + 1]], fill=INK, width=4)\n    if t > 0.6:\n        # gold inlay pattern \u2013 crossed lines inside shield\n        inlay_t = (t - 0.6) / 0.4\n        # diagonal cross\n        _line(draw, (cx - 120, cy - 50), (cx + 120, cy + 150),\n              inlay_t, GOLD, width=3)\n        _line(draw, (cx + 120, cy - 50), (cx - 120, cy + 150),\n              inlay_t, GOLD, width=3)\n        # central gold circle\n        _circle(draw, (cx, cy + 50), 40, inlay_t, fill=GOLD, outline=GOLD_DARK)\n    return img\nSCENE_FUNCTIONS.append(scene_s008)\n\n# --- s009 : calligraphic Phi (\u03a6) with gold ornament ---\ndef scene_s009(frame):\n    img = Image.new('RGBA', (WIDTH, HEIGHT), PARCHMENT)\n    draw = ImageDraw.Draw(img)\n    t = min(frame, TOTAL_FRAMES - 1) / (TOTAL_FRAMES - 1)\n\n    cx, cy = WIDTH // 2, HEIGHT // 2\n    # outer circle (ink)\n    _circle(draw, (cx, cy), 200, t * 0.5, outline=INK, width=5)\n    # vertical bar (appears later)\n    bar_t = max(0, (t - 0.3) / 0.4)\n    _line(draw, (cx, cy - 200), (cx, cy + 200), bar_t, INK, width=8)\n    # gold accents: two dots in the circles' intersections (if any) (artistic)\n    if t > 0.5:\n        gold_t = (t - 0.5) / 0.5\n        _circle(draw, (cx - 80, cy - 80), 15, gold_t, fill=GOLD, outline=GOLD_DARK)\n        _circle(draw, (cx + 80, cy + 80), 15, gold_t, fill=GOLD, outline=GOLD_DARK)\n       "